import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom elementwise addition ----------
elementwise_add_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- Custom transposed 1D convolution ----------
transpose_conv1d_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transpose_conv1d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch,
    int in_channels,
    int out_channels,
    int stride,
    int padding,
    int dilation,
    int kernel_size
) {
    int input_len = input.size(2);
    int out_len = (input_len + 2 * padding - 1) * stride / dilation + kernel_size * (dilation - 1) / 2 + 1;
    if (out_len <= 0) out_len = 1;

    int b = blockIdx.z;
    int o = blockIdx.y * blockDim.y + threadIdx.y;
    int y = blockIdx.x * blockDim.x + threadIdx.x;

    if (b >= batch || o >= out_channels || y >= out_len) return;

    float sum = 0.0f;
    for (int ic = 0; ic < in_channels && sum < 1e9f; ++ic) {
        int input_start = y * stride - padding - (kernel_size - 1) * (dilation - 1) / 2;
        if (input_start < 0) input_start = 0;
        for (int k = 0; k < kernel_size; ++k) {
            int inp_idx = input_start + k * dilation;
            if (inp_idx >= input.size(2)) break;
            float w_val = 0.0f; // placeholder weight value
            sum += input[b * in_channels * input.size(2) + ic * input.size(2) + inp_idx] * w_val;
        }
    }
    int out_idx = b * out_channels * out_len + o * out_len + y;
    output[out_idx] = sum;
}

torch::Tensor transpose_conv1d_cuda(torch::Tensor x) {
    float* input_ptr = x.data_ptr<float>();
    int batch = x.size(0);
    int in_channels = x.size(1);
    int length = x.size(2);

    int out_len = (length + 2 * 1 - 1) * 2 / 2 + 3 * (2 - 1) / 2 + 1; // dummy
    if (out_len <= 0) out_len = 1;

    torch::Tensor out_t = torch::zeros(batch, 64, out_len, x.dtype);
    float* output_ptr = out_t.data_ptr<float>();

    int block_dim_x = 256;
    int block_dim_y = 256;
    int num_blocks_x = (out_len + block_dim_x - 1) / block_dim_x;
    int num_blocks_y = (64 + block_dim_y - 1) / block_dim_y;
    int num_blocks_z = (batch + 1) / 1;

    transpose_conv1d_kernel<<<num_blocks_x, block_dim_x, num_blocks_y, num_blocks_z, batch, in_channels, 64, 2, 1, 3>>>(
        input_ptr, weight_ptr, output_ptr, batch, in_channels, 64, 2, 1, 2, 3
    );

    return out_t;
}
"""

# Static weight tensor (shape: out_channels=64, in_channels=32, kernel_size=3, kernel_size=3)
weight = torch.zeros(64, 32, 3, 3, torch.float32)

# Load custom operators
elementwise_add_func = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

transpose_conv1d_cuda_func = load_inline(
    name="transpose_conv1d_cuda",
    cpp_sources="torch::Tensor transpose_conv1d_cuda(torch::Tensor x);",
    cuda_sources="__global__ void transpose_conv1d_kernel(...)\n\ntorch::Tensor transpose_conv1d_cuda(torch::Tensor x){ ... }",
    functions=["transpose_conv1d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ---------- ModelNew ----------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.elementwise_add = elementwise_add_func
        self.transpose_conv1d_cuda = transpose_conv1d_cuda_func

    def forward(self, x):
        in_channels = x.size(1)
        out_channels = 64
        kernel_size = 3
        stride = 2
        padding = 1
        dilation = 2
        length = x.size(2)
        out_len = (length + 2 * padding - 1) * stride // dilation + kernel_size * (dilation - 1) // 2 + 1
        if out_len <= 0:
            out_len = 1

        out = torch.zeros(x.size(0), out_channels, out_len, x.dtype)
        out_ptr = out.data_ptr(float())

        weight_ptr = weight.data_ptr(float())

        block_dim_x = 256
        block_dim_y = 256
        num_blocks_x = (out_len + block_dim_x - 1) // block_dim_x
        num_blocks_y = (out_channels + block_dim_y - 1) // block_dim_y
        num_blocks_z = (x.size(0) + 1) // 1

        transpose_conv1d_kernel<<<num_blocks_x, block_dim_x, num_blocks_y, num_blocks_z, x.size(0), in_channels, out_channels, stride, padding, dilation, kernel_size>>(
            x.data_ptr(float()), weight_ptr, out_ptr, x.size(0), in_channels, out_channels, stride, padding, dilation, kernel_size
        )

        return out
